INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_DIXON_KENNEDY_SLAVIC','secondary scholarship','Mike Dixon-Kennedy, Encyclopedia of Russian and Slavic Myth and Legend (ABC-CLIO, Santa Barbara, 1998)','South Slavic and pan-Slavic deities and folk beings'),
 ('SRC_RALSTON_RUSSIAN_FOLK','secondary scholarship','W. R. S. Ralston, The Songs of the Russian People, as Illustrative of Slavonic Mythology and Russian Social Life (Ellis & Green, London, 1872)','Slavic folk ritual, nature spirits, and rain-magic customs')
INSERT INTO _e VALUES
 ('ENT_SSL_DABOG','Dabog','God','God','Slavic','sun; earth; underworld wealth','B','South-Slavic (chiefly Serbian) reflex of the sun-god, attested in Serbian folklore as ''Dabog''/''Daba'', a chthonic lord of the earth and of silver/gold often demonized in folk-Christian tradition; cognate of the East-Slavic Dažbog.'),
 ('ENT_SSL_VILA','Vila','Collective','Collective','Slavic','mountains; waters; woodland; fate','B','South-Slavic nymph-class (vila, pl. vile; Bulgarian samodiva/samovila) — beautiful winged female nature-spirits of mountains, springs and clouds in Serbian/Croatian/Bulgarian folklore; distinct from the East-Slavic water-spirit Rusalka.'),
 ('ENT_SSL_GERMAN','German (Herman)','Spirit','Spirit','Slavic','rain; fertility; agrarian rite','C','South-Slavic (Bulgarian/Serbian) rain-ritual figure: a small clay or dough effigy made, mourned and ''buried'' or cast into water by women in a rain-making rite to end drought; attested ethnographically rather than as a cult god.'),
 ('ENT_SSL_VID','Vid','God','God','Slavic','sky; light; oath','C','Reconstructed South-Slavic theonym ''Vid'' surviving in Croatian toponymy and folk usage (e.g. Vidova Gora) and folk-Christianized onto St Vitus (Sveti Vid); related to the West-Slavic -vit theophoric element (Svetovit). Attestation is indirect/onomastic.'),
 ('ENT_SSL_PROVE','Prove','God','God','Slavic','oak groves; law; justice','B','West-Slavic (Wagrian/Polabian) god of the land of Oldenburg, worshipped in a sacred oak grove without an idol; named by Helmold of Bosau, Chronica Slavorum (c. 1170); often read as a god of law/justice (cf. Prove ~ pravo).'),
 ('ENT_SSL_PRIPEGALA','Pripegala','God','God','Slavic','orgiastic fertility; bloody sacrifice','C','West-Slavic (Polabian) deity known only from the Magdeburg letter (c. 1108), which decries his cult of orgiastic rites and decapitated-victim sacrifice; etymology and exact function disputed (sometimes likened to Priapus/Belial by the Latin source).'),
 ('ENT_SSL_TJARNAGLOFI','Tjarnaglofi','God','God','Slavic','war; victory; augury','C','West-Slavic (Pomeranian) war-god whose silver-mustachioed idol was a Rani battle-talisman; named in the Knytlinga saga as captured by the Danes (1168). Norse-transmitted theonym for a Rügen-area Slavic god.');
