INSERT INTO _p VALUES
 ('ENT_SSL_DABOG','PER_SLAV_PAGAN','South-Slavic (chiefly Serbian) reflex of the sun-god, attested in Serbian folklore as ''Dabog''/''Daba'', a chthonic lord of the earth and of silver/gold often demonized in folk-Christian tradition; cognate of the East-Slavic Dažbog.'),
 ('ENT_SSL_VILA','PER_SLAV_PAGAN','South-Slavic nymph-class (vila, pl. vile; Bulgarian samodiva/samovila) — beautiful winged female nature-spirits of mountains, springs and clouds in Serbian/Croatian/Bulgarian folklore; distinct from the East-Slavic water-spirit Rusalka.'),
 ('ENT_SSL_GERMAN','PER_SLAV_PAGAN','South-Slavic (Bulgarian/Serbian) rain-ritual figure: a small clay or dough effigy made, mourned and ''buried'' or cast into water by women in a rain-making rite to end drought; attested ethnographically rather than as a cult god.'),
 ('ENT_SSL_VID','PER_SLAV_PAGAN','Reconstructed South-Slavic theonym ''Vid'' surviving in Croatian toponymy and folk usage (e.g. Vidova Gora) and folk-Christianized onto St Vitus (Sveti Vid); related to the West-Slavic -vit theophoric element (Svetovit). Attestation is indirect/onomastic.'),
 ('ENT_SSL_PROVE','PER_SLAV_PAGAN','West-Slavic (Wagrian/Polabian) god of the land of Oldenburg, worshipped in a sacred oak grove without an idol; named by Helmold of Bosau, Chronica Slavorum (c. 1170); often read as a god of law/justice (cf. Prove ~ pravo).'),
 ('ENT_SSL_PRIPEGALA','PER_SLAV_PAGAN','West-Slavic (Polabian) deity known only from the Magdeburg letter (c. 1108), which decries his cult of orgiastic rites and decapitated-victim sacrifice; etymology and exact function disputed (sometimes likened to Priapus/Belial by the Latin source).'),
 ('ENT_SSL_TJARNAGLOFI','PER_SLAV_PAGAN','West-Slavic (Pomeranian) war-god whose silver-mustachioed idol was a Rani battle-talisman; named in the Knytlinga saga as captured by the Danes (1168). Norse-transmitted theonym for a Rügen-area Slavic god.');
