INSERT INTO _r VALUES
 ('ENT_SSL_DABOG','member_of','ENT_SLAV_PANTHEON','high','Dabog is a South-Slavic high deity belonging to the broader Slavic pantheon hub.'),
 ('ENT_SSL_DABOG','aligned_with','ENT_SLAV_DAZBOG','high','Dabog is the South-Slavic (Serbian) cognate/reflex of the East-Slavic sun-god Dažbog; same theonym (modern cognate => aligned_with since cognate_of is unavailable).'),
 ('ENT_SSL_DABOG','aligned_with','ENT_SLAV_VELES','medium','In Serbian folk tradition Dabog is a chthonic lord of underground wealth, a role overlapping the chthonic Veles.'),
 ('ENT_SSL_VILA','member_of','ENT_SLAV_FOLK_SPIRITS','high','The vile are a South-Slavic class of nature-spirits within the Slavic domestic-and-nature-spirit grouping.'),
 ('ENT_SSL_VILA','aligned_with','ENT_SLAV_RUSALKA','medium','Vile are the South-Slavic functional counterpart of the East-Slavic Rusalka water/nature nymphs, but a distinct class (homonym caution noted).'),
 ('ENT_SSL_GERMAN','member_of','ENT_SLAV_FOLK_SPIRITS','medium','German is a folk ritual fertility/rain figure within the Slavic folk-spirit complex.'),
 ('ENT_SSL_GERMAN','aligned_with','ENT_SLAV_KUPALA','medium','The German rain-effigy rite parallels other Slavic seasonal effigy/agrarian rites such as the Kupala observances.'),
 ('ENT_SSL_VID','member_of','ENT_SLAV_PANTHEON','medium','Vid is a reconstructed South-Slavic theonym placed within the Slavic pantheon.'),
 ('ENT_SSL_VID','aligned_with','ENT_SLAV_SVETOVIT','medium','Vid shares the -vit theophoric element and light/sky associations with the West-Slavic Svetovit (Sventovit).'),
 ('ENT_SSL_PROVE','member_of','ENT_SLAV_PANTHEON','high','Prove is a Polabian Slavic god belonging to the Slavic pantheon hub.'),
 ('ENT_SSL_PRIPEGALA','member_of','ENT_SLAV_PANTHEON','medium','Pripegala is a Polabian Slavic deity assigned to the Slavic pantheon hub.'),
 ('ENT_SSL_TJARNAGLOFI','member_of','ENT_SLAV_PANTHEON','high','Tjarnaglofi is a Pomeranian Slavic war-god belonging to the Slavic pantheon hub.'),
 ('ENT_SSL_TJARNAGLOFI','aligned_with','ENT_SLAV_RUGIEVIT','medium','Tjarnaglofi was a Rani (Rügen-area) war-idol alongside the other West-Slavic war-gods such as Rugievit.');
